import sys


def main():
    # 核心思路: 回溯枚举，每个数字从按键字母表选一个字符，拼接出所有组合。
    # 关键步骤: i 表示当前数字下标，path 保存已选字母，递归到底即得到一个组合。
    # 易错点: 输入为空串时直接返回空列表，不应把空串当作一个组合。
    # 复杂度: 时间 O(4^n·n)，空间 O(n) 递归栈与 path 长度。
    digits = sys.stdin.readline().strip()
    if not digits:
        return
    mp = {'2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
          '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'}
    res = []

    def dfs(i, path):
        if i == len(digits):
            res.append(''.join(path))
            return
        for ch in mp[digits[i]]:
            path.append(ch)
            dfs(i + 1, path)
            path.pop()

    dfs(0, [])
    for s in res:
        print(s)

if __name__ == "__main__":
    main()

