class Solution {
public:
    vector<string> letterCombinations(string digits) {
        // 核心思路: 回溯枚举，每个数字从按键字母表选一个字符，拼接出所有组合。
        // 关键步骤: i 表示当前位，path 记录已选字母，递归后用 pop_back 恢复现场。
        // 易错点: 空输入直接返回空数组，字符映射需覆盖数字 2 到 9。
        // 复杂度: 时间 O(4^n·n)，空间 O(n) 递归栈。
        if (digits.empty()) return {};
        unordered_map<char, string> mp = {
            {'2', "abc"}, {'3', "def"}, {'4', "ghi"}, {'5', "jkl"},
            {'6', "mno"}, {'7', "pqrs"}, {'8', "tuv"}, {'9', "wxyz"}
        };
        vector<string> res;
        string path;
        function<void(int)> dfs = [&](int i) {
            if (i == (int)digits.size()) { res.push_back(path); return; }
            for (char ch : mp[digits[i]]) {  // 按按键字母表顺序，保证确定性输出
                path.push_back(ch);
                dfs(i + 1);
                path.pop_back();
            }
        };
        dfs(0);
        return res;
    }
};

