class Solution {
public:
    vector<string> generateParenthesis(int n) {
        // 核心思路: 回溯生成合法括号串，任何前缀的右括号数都不超过左括号数。
        // 关键步骤: openCnt 与 closeCnt 统计已放括号数，长度到 2n 时收束。
        // 易错点: 只有 closeCnt 小于 openCnt 时才允许放右括号，保证合法性。
        // 复杂度: 结果数为卡特兰数，时间 O(4^n / sqrt(n))，空间 O(n)。
        vector<string> res;
        string path;
        function<void(int, int)> dfs = [&](int openCnt, int closeCnt) {
            if ((int)path.size() == 2 * n) { res.push_back(path); return; }
            if (openCnt < n) {  // 先放左括号，保证确定性顺序
                path.push_back('(');
                dfs(openCnt + 1, closeCnt);
                path.pop_back();
            }
            if (closeCnt < openCnt) {
                path.push_back(')');
                dfs(openCnt, closeCnt + 1);
                path.pop_back();
            }
        };
        dfs(0, 0);
        return res;
    }
};

