class Solution {
public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        // 核心思路: 回溯加剪枝，每个数可以重复选取，用 start 限制下标只增不减。
        // 关键步骤: remain 减到 0 时记录答案，候选值大于 remain 时跳过该分支。
        // 易错点: 递归时仍传当前下标 i，才能让同一个数字被重复使用。
        // 复杂度: 最坏指数级时间，空间 O(target / min) 递归深度。
        vector<vector<int>> res;
        vector<int> path;
        int n = candidates.size();
        function<void(int, int)> dfs = [&](int start, int remain) {
            if (remain == 0) { res.push_back(path); return; }
            for (int i = start; i < n; i++) {  // 下标只增不减，避免重复组合
                if (candidates[i] > remain) continue;
                path.push_back(candidates[i]);
                dfs(i, remain - candidates[i]);
                path.pop_back();
            }
        };
        dfs(0, target);
        return res;
    }
};

