class Solution {
public:
    vector<vector<int>> permute(vector<int>& nums) {
        // 核心思路: 回溯生成全排列，用 used 数组标记哪些下标已被选取。
        // 关键步骤: 每层按下标递增顺序尝试未用元素，递归返回后撤销选择。
        // 易错点: 撤销时必须同时弹出 path 并复位 used，保证现场完全还原。
        // 复杂度: 时间 O(n·n!)，空间 O(n) 递归栈。
        vector<vector<int>> res;
        int n = nums.size();
        vector<bool> used(n, false);
        vector<int> path;
        function<void()> dfs = [&]() {
            if ((int)path.size() == n) { res.push_back(path); return; }
            for (int i = 0; i < n; i++) {  // 按下标递增顺序尝试，保证确定性输出
                if (used[i]) continue;
                used[i] = true;
                path.push_back(nums[i]);
                dfs();
                path.pop_back();
                used[i] = false;
            }
        };
        dfs();
        return res;
    }
};

